import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.il0noOp3.js";const p=JSON.parse(`{"title":"Service Coverage Gap","description":"For each of the 18 Azure portal service categories, every Azure service Microsoft publishes in that category, marked Collected or Not collected against AzureScout's 242 collectors.","frontmatter":{"description":"For each of the 18 Azure portal service categories, every Azure service Microsoft publishes in that category, marked Collected or Not collected against AzureScout's 242 collectors."},"headers":[],"relativePath":"reference/service-coverage-gap.md","filePath":"reference/service-coverage-gap.md"}`),c={name:"reference/service-coverage-gap.md"};function a(s,t,i,l,n,u){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="service-coverage-gap" tabindex="-1">Service Coverage Gap <a class="header-anchor" href="#service-coverage-gap" aria-label="Permalink to &quot;Service Coverage Gap&quot;">​</a></h1><p><a href="./coverage-table.html">Coverage Table</a> and <a href="./arm-modules.html">ARM Modules</a> list every collector AzureScout <strong>has</strong>, grouped by category. This page inverts that question: for each of the 18 categories, what does Microsoft publish under that category, and which of those services do we actually collect?</p><div class="warning custom-block"><p class="custom-block-title">This page is hand-maintained, not generated</p><p>Unlike <a href="./coverage-table.html">Coverage Table</a> and <a href="./arm-modules.html">ARM Modules</a> — which regenerate from <code>manifests/collectors/</code> and cannot drift — the &quot;what Microsoft publishes&quot; half of this page comes from external Microsoft sources that are not available to a build-time script (Microsoft does not publish a machine-readable per-portal-category product feed). The &quot;what we collect&quot; half is cross-checked against <a href="./coverage-table.html">Coverage Table</a>, which <em>is</em> generated, but the page as a whole needs a periodic manual re-fetch against the source URLs below — Microsoft&#39;s own catalogue drifts (services rename, rebrand, and retire) faster than most of this repository.</p></div><h2 id="sources-and-method" tabindex="-1">Sources and method <a class="header-anchor" href="#sources-and-method" aria-label="Permalink to &quot;Sources and method&quot;">​</a></h2><ul><li><strong>Product catalogue</strong>: <a href="https://azure.microsoft.com/en-us/products/" target="_blank" rel="noreferrer">azure.microsoft.com/products</a>, filtered per category (e.g. <code>?categories=compute</code>). This is Microsoft&#39;s own product-category taxonomy and the closest public equivalent to the Azure portal&#39;s &quot;All services&quot; category groupings that <a href="./category-structure.html">Category Structure</a> is built on. <strong>Fetched 2026-08-04.</strong></li><li><strong>Azure Monitor</strong> has no entry on that catalogue page (<code>?categories=monitor</code> 404s) — Monitor&#39;s products are folded into the &quot;DevOps&quot; and &quot;Management and governance&quot; pages there instead. For Monitor, the sub-item list below is sourced from Microsoft Learn&#39;s <a href="https://learn.microsoft.com/azure/azure-monitor/fundamentals/overview" target="_blank" rel="noreferrer">Azure Monitor overview</a> and <a href="https://learn.microsoft.com/azure/azure-monitor/fundamentals/enterprise-monitoring-architecture" target="_blank" rel="noreferrer">Azure Monitor enterprise monitoring architecture</a> articles. <strong>Fetched 2026-08-04.</strong></li><li><strong>General</strong> has no public product catalogue entry either — &quot;Support tickets&quot;, &quot;Reservations&quot; and &quot;VM quotas&quot; are platform surfaces, not marketed products. See the note in that section; no sourced count is given for it, rather than inventing one.</li><li><strong>What we collect</strong>: read directly off <a href="./coverage-table.html">Coverage Table</a>, which is generated from <code>manifests/collectors/**/*.psd1</code> by <code>scripts/Build-ArmModuleCatalog.ps1</code>.</li><li>A service is marked <strong>Collected</strong> only when a specific collector&#39;s <code>ResourceTypes</code> targets that service&#39;s ARM resource type (or, for Entra/Graph-backed services, its Graph endpoint). A service that would incidentally appear as a generic <code>virtualMachines</code> or <code>storageAccounts</code> row (for example &quot;Linux Virtual Machines&quot; or &quot;Data Science Virtual Machines&quot;) is marked Collected only if there is no dedicated resource type to miss; otherwise it is called out as its own row.</li><li><strong>Commonly cited figures</strong> (22 for AI + Machine Learning, 32 for Compute, 12 for Containers) are checked against the sourced counts in each section, not assumed to be correct — see the discrepancy notes.</li></ul><h2 id="coverage-summary" tabindex="-1">Coverage summary <a class="header-anchor" href="#coverage-summary" aria-label="Permalink to &quot;Coverage summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Microsoft services (sourced)</th><th>Collected</th><th>Not collected</th><th>Coverage</th><th>Cited figure</th><th>Matches?</th></tr></thead><tbody><tr><td>AI + Machine Learning</td><td>31</td><td>16</td><td>15</td><td>52%</td><td>22</td><td>No — see note</td></tr><tr><td>Analytics</td><td>19</td><td>6</td><td>13</td><td>32%</td><td>—</td><td>—</td></tr><tr><td>Compute</td><td>22</td><td>14</td><td>8</td><td>64%</td><td>32</td><td>No — see note</td></tr><tr><td>Containers</td><td>9</td><td>7</td><td>2</td><td>78%</td><td>12</td><td>No — see note</td></tr><tr><td>Databases</td><td>15</td><td>10</td><td>5</td><td>67%</td><td>—</td><td>—</td></tr><tr><td>DevOps</td><td>19</td><td>8</td><td>11</td><td>42%</td><td>—</td><td>—</td></tr><tr><td>General</td><td>ambiguous — no published catalogue</td><td>4 of AzureScout&#39;s own 5</td><td>n/a</td><td>n/a</td><td>—</td><td>—</td></tr><tr><td>Hybrid + multicloud</td><td>14 (marketing list) / ambiguous, see note</td><td>16 collectors, 2 known resource-family gaps</td><td>Custom Locations; Arc-enabled VMware/SCVMM</td><td>n/a</td><td>—</td><td>—</td></tr><tr><td>Identity</td><td>4 (product-level; ambiguous, see note)</td><td>all 4 present</td><td>0</td><td>n/a</td><td>—</td><td>—</td></tr><tr><td>Integration</td><td>7</td><td>5</td><td>2</td><td>71%</td><td>—</td><td>—</td></tr><tr><td>Internet of Things</td><td>16</td><td>6</td><td>10</td><td>38%</td><td>—</td><td>—</td></tr><tr><td>Management and governance</td><td>25</td><td>12</td><td>13</td><td>48%</td><td>—</td><td>—</td></tr><tr><td>Migration</td><td>6</td><td>6</td><td>0</td><td>100%</td><td>—</td><td>—</td></tr><tr><td>Monitor</td><td>14 (Learn-derived)</td><td>13</td><td>1</td><td>93%</td><td>—</td><td>—</td></tr><tr><td>Networking</td><td>22</td><td>17</td><td>5</td><td>77%</td><td>—</td><td>—</td></tr><tr><td>Security</td><td>19</td><td>13</td><td>6</td><td>68%</td><td>—</td><td>—</td></tr><tr><td>Storage</td><td>19</td><td>11</td><td>8</td><td>58%</td><td>—</td><td>—</td></tr><tr><td>Web &amp; Mobile</td><td>15 (union of Web + Mobile)</td><td>12</td><td>3</td><td>80%</td><td>—</td><td>—</td></tr></tbody></table><p>Percentages exclude items marked N/A (not an ARM resource — an OS, an SDK, a GitHub product, or a non-resource capability) from both the numerator and denominator; those rows are still listed so nothing is silently dropped.</p><h2 id="ai-machine-learning" tabindex="-1">AI + Machine Learning <a class="header-anchor" href="#ai-machine-learning" aria-label="Permalink to &quot;AI + Machine Learning&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=ai-machine-learning" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=ai-machine-learning</a>, fetched 2026-08-04 — 31 products.</p><div class="warning custom-block"><p class="custom-block-title">A commonly cited figure of 22 does not match the sourced count (31)</p><p>Microsoft&#39;s AI + Machine Learning catalogue lists 31 named products as of this fetch, most of them the &quot;Foundry&quot;-branded rename of the individual Cognitive Services APIs (Vision, Language, Speech, Document Intelligence, Content Safety, etc.) that shipped through 2025–2026. If 22 came from an older snapshot of the same page (pre-Foundry rebrand) or from the Azure portal&#39;s own <strong>AI + Machine Learning</strong> blade rather than this catalogue, that would explain the gap — we did not find a source that lists exactly 22.</p></div><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Microsoft Foundry (hub/project)</td><td>Collected</td><td><code>AIFoundryHubs</code>, <code>AIFoundryProjects</code></td></tr><tr><td>Azure AI Bot Service</td><td>Collected</td><td><code>BotServices</code></td></tr><tr><td>Azure AI Search</td><td>Collected</td><td><code>SearchServices</code>, <code>SearchIndexes</code></td></tr><tr><td>Azure Databricks</td><td>Collected (cross-category: Analytics)</td><td><code>Databricks</code></td></tr><tr><td>Azure Machine Learning</td><td>Collected</td><td><code>MachineLearning</code>, <code>MLComputes</code>, <code>MLDatasets</code>, <code>MLDatastores</code>, <code>MLEndpoints</code>, <code>MLModels</code>, <code>MLPipelines</code></td></tr><tr><td>Azure Open Datasets</td><td>Not collected</td><td>— (data catalogue, not an inventoried resource)</td></tr><tr><td>Foundry Tools (Vision/Language/etc. umbrella)</td><td>Collected</td><td>see individual Cognitive Services rows below</td></tr><tr><td>Azure AI Video Indexer</td><td>Not collected</td><td>—</td></tr><tr><td>Azure AI Custom Vision</td><td>Collected</td><td><code>CustomVision</code></td></tr><tr><td>Data Science Virtual Machines</td><td>Not collected</td><td>no dedicated collector (would appear only as a generic <code>VirtualMachine</code> row)</td></tr><tr><td>Azure AI Language (Foundry Tools)</td><td>Collected</td><td><code>TextAnalytics</code></td></tr><tr><td>Azure AI Translator (Foundry Tools)</td><td>Collected</td><td><code>Translator</code></td></tr><tr><td>Azure AI Metrics Advisor</td><td>Not collected</td><td>—</td></tr><tr><td>Azure OpenAI (Foundry Models)</td><td>Collected</td><td><code>OpenAIAccounts</code>, <code>OpenAIDeployments</code></td></tr><tr><td>Azure AI Personalizer</td><td>Not collected</td><td>—</td></tr><tr><td>Content Safety (Foundry Control Plane)</td><td>Collected</td><td><code>ContentSafety</code></td></tr><tr><td>Health Bot</td><td>Not collected</td><td>—</td></tr><tr><td>Azure Document Intelligence (Foundry Tools)</td><td>Collected</td><td><code>FormRecognizer</code></td></tr><tr><td>AI Anomaly Detector</td><td>Not collected</td><td>—</td></tr><tr><td>Foundry Models</td><td>Partially collected</td><td><code>OpenAIDeployments</code> covers OpenAI; other Foundry model families are not enumerated</td></tr><tr><td>Microsoft Security Copilot</td><td>Not collected</td><td>—</td></tr><tr><td>Azure AI Immersive Reader</td><td>Collected</td><td><code>ImmersiveReader</code></td></tr><tr><td>Phi open models</td><td>N/A</td><td>model weights, not an ARM resource</td></tr><tr><td>Azure Content Understanding (Foundry Tools)</td><td>Not collected</td><td>—</td></tr><tr><td>Azure AI Speech (Foundry Tools)</td><td>Collected</td><td><code>SpeechService</code></td></tr><tr><td>Microsoft Planetary Computer Pro</td><td>Not collected</td><td>—</td></tr><tr><td>Foundry Agent Service</td><td>Not collected</td><td>—</td></tr><tr><td>Azure SRE Agent</td><td>Not collected</td><td>—</td></tr><tr><td>Observability (Foundry Control Plane)</td><td>Not collected</td><td>—</td></tr><tr><td>Azure AI Vision (Foundry Tools)</td><td>Collected</td><td><code>ComputerVision</code></td></tr><tr><td>Foundry IQ</td><td>Not collected</td><td>—</td></tr></tbody></table><p>We also collect <code>AppliedAIServices</code>, <code>AzureAI</code>, <code>FaceAPI</code> and <code>HealthInsights</code> — general or older Cognitive Services surfaces that Microsoft&#39;s current catalogue folds into &quot;Foundry Tools&quot; rather than listing individually, so they are not double-counted above.</p><p>We also collect <code>ContentModerator</code> (<code>microsoft.cognitiveservices/accounts</code>, <code>Kind -eq &#39;ContentModerator&#39;</code>), which does not appear in the table above because Microsoft retired it: Content Moderator has been unavailable for new resource creation since 15 March 2024 and is scheduled for full retirement on 15 March 2027, replaced by Azure AI Content Safety (already tracked above as <code>ContentSafety</code>). Same shape as the <code>MariaDB</code>/<code>SQLPOOL</code> note under Databases — a working collector pointed at a decommissioned service, not a coverage gap.</p><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=analytics" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=analytics</a>, fetched 2026-08-04 — 19 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Azure Analysis Services</td><td>Not collected</td><td>—</td></tr><tr><td>Azure Data Explorer</td><td>Collected</td><td><code>DataExplorerCluster</code></td></tr><tr><td>Azure Data Factory</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Data Lake Storage</td><td>Collected (cross-category: Storage)</td><td><code>StorageAccounts</code> (Gen2 accounts are still <code>microsoft.storage/storageaccounts</code>)</td></tr><tr><td>Azure Data Share</td><td>Not collected</td><td>—</td></tr><tr><td>Azure Databricks</td><td>Collected</td><td><code>Databricks</code></td></tr><tr><td>Azure Stream Analytics</td><td>Collected</td><td><code>Streamanalytics</code></td></tr><tr><td>Azure Synapse Analytics</td><td>Collected</td><td><code>Synapse</code></td></tr><tr><td>Data Catalog</td><td>N/A</td><td>Microsoft retired Azure Data Catalog in 2022</td></tr><tr><td>Data Lake Analytics</td><td>N/A</td><td>Microsoft retired Azure Data Lake Analytics in 2024</td></tr><tr><td>Event Hubs</td><td>Collected</td><td><code>EvtHub</code> (namespaces); <code>EventHubClusters</code> also collected under Integration</td></tr><tr><td>HDInsight</td><td>Not collected</td><td>real gap</td></tr><tr><td>Power BI Embedded</td><td>Not collected</td><td>—</td></tr><tr><td>Microsoft Graph Data Connect</td><td>Not collected</td><td>—</td></tr><tr><td>Azure Chaos Studio</td><td>Collected (cross-category: DevOps)</td><td><code>ChaosStudio</code></td></tr><tr><td>Microsoft Fabric</td><td>Not collected</td><td>real gap — no Fabric capacity/workspace collector exists</td></tr><tr><td>Microsoft Purview</td><td>Collected</td><td><code>Purview</code></td></tr><tr><td>Power BI</td><td>Not collected</td><td>—</td></tr><tr><td>Microsoft Planetary Computer Pro</td><td>Not collected</td><td>—</td></tr></tbody></table><h2 id="compute" tabindex="-1">Compute <a class="header-anchor" href="#compute" aria-label="Permalink to &quot;Compute&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=compute" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=compute</a>, fetched 2026-08-04 — 22 products.</p><div class="warning custom-block"><p class="custom-block-title">A commonly cited figure of 32 does not match the sourced count (22)</p><p>Microsoft&#39;s Compute catalogue lists 22 named products. We found no Microsoft source — marketing catalogue, Azure portal category, or Learn taxonomy page — that lists 32 for Compute. If 32 came from counting VM series/SKU families (Dv5, Ev5, NCv3, etc.) rather than products, that is a different and much larger axis than &quot;sub-services&quot; and is not what this page tracks.</p></div><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>App Service</td><td>Collected (cross-category: Web)</td><td><code>APPServices</code>, <code>APPServicePlan</code></td></tr><tr><td>Azure Compute Fleet</td><td>Not collected</td><td>real gap — new (2024) service, no <code>microsoft.computefleet</code> collector</td></tr><tr><td>Azure Quantum</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Spot Virtual Machines</td><td>Collected</td><td><code>VirtualMachine</code> (same resource type, priority attribute)</td></tr><tr><td>Azure Spring Apps</td><td>Collected (cross-category: Web)</td><td><code>SpringApps</code></td></tr><tr><td>Azure VMware Solution</td><td>Collected</td><td><code>VMWare</code></td></tr><tr><td>Batch</td><td>Not collected</td><td>real gap — no <code>microsoft.batch</code> collector</td></tr><tr><td>Cloud Services</td><td>Not collected</td><td>legacy/retiring platform</td></tr><tr><td>Linux Virtual Machines</td><td>Collected</td><td><code>VirtualMachine</code> (same resource type as Windows)</td></tr><tr><td>SQL Server on Azure Virtual Machines</td><td>Collected (cross-category: Databases)</td><td><code>SQLVM</code></td></tr><tr><td>Static Web Apps</td><td>Collected (cross-category: Web)</td><td><code>StaticWebApps</code></td></tr><tr><td>Virtual Machine Scale Sets</td><td>Collected</td><td><code>VirtualMachineScaleSet</code></td></tr><tr><td>Virtual Machines</td><td>Collected</td><td><code>VirtualMachine</code>, <code>VMDisk</code>, <code>VMOperationalData</code></td></tr><tr><td>Azure Virtual Desktop</td><td>Collected</td><td><code>AVD</code>, <code>AVDApplicationGroups</code>, <code>AVDApplications</code>, <code>AVDAzureLocal</code>, <code>AVDScalingPlans</code>, <code>AVDSessionHosts</code>, <code>AVDWorkspaces</code></td></tr><tr><td>Windows Server</td><td>N/A</td><td>operating system, not an ARM resource</td></tr><tr><td>Azure Dedicated Host</td><td>Not collected</td><td>real gap — no <code>microsoft.compute/dedicatedhosts</code> collector</td></tr><tr><td>Azure VM Image Builder</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Kubernetes Service (AKS)</td><td>Collected (cross-category: Containers)</td><td><code>AKS</code></td></tr><tr><td>Azure Functions</td><td>Collected (cross-category: Web)</td><td><code>FunctionApps</code></td></tr><tr><td>Azure Container Instances</td><td>Collected (cross-category: Containers)</td><td><code>ContainerGroups</code></td></tr><tr><td>Azure Container Apps</td><td>Collected (cross-category: Containers)</td><td><code>ContainerApp</code>, <code>ContainerAppEnv</code></td></tr><tr><td>Nutanix Cloud Clusters on Azure</td><td>Not collected</td><td>real gap — 2024 partner-hosted service</td></tr></tbody></table><p><code>AvailabilitySets</code> is also collected but does not appear as its own line item in Microsoft&#39;s catalogue (it is a sub-feature of Virtual Machines there).</p><h2 id="containers" tabindex="-1">Containers <a class="header-anchor" href="#containers" aria-label="Permalink to &quot;Containers&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=containers" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=containers</a>, fetched 2026-08-04 — 9 products.</p><div class="warning custom-block"><p class="custom-block-title">A commonly cited figure of 12 does not match the sourced count (9)</p><p>Microsoft&#39;s Containers catalogue lists 9 products. It does not separately list Azure Container Storage sub-features, Draft, or KEDA as distinct products the way some internal container-platform documentation does, which may explain a larger internal count; we could not source 12 from a Microsoft product page.</p></div><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>App Configuration</td><td>Collected (cross-category: DevOps)</td><td><code>AppConfiguration</code></td></tr><tr><td>Azure Kubernetes Service (AKS)</td><td>Collected</td><td><code>AKS</code></td></tr><tr><td>Azure Kubernetes Fleet Manager</td><td>Not collected</td><td>real gap — no <code>microsoft.containerservice/fleets</code> collector</td></tr><tr><td>Azure Red Hat OpenShift</td><td>Collected</td><td><code>ARO</code></td></tr><tr><td>Azure Container Apps</td><td>Collected</td><td><code>ContainerApp</code>, <code>ContainerAppEnv</code></td></tr><tr><td>Azure Functions</td><td>Collected (cross-category: Web)</td><td><code>FunctionApps</code></td></tr><tr><td>Azure Container Instances</td><td>Collected</td><td><code>ContainerGroups</code></td></tr><tr><td>Azure Container Registry</td><td>Collected</td><td><code>ContainerRegistries</code></td></tr><tr><td>Azure Container Storage</td><td>Not collected</td><td>real gap — no <code>microsoft.containerstorage</code> collector</td></tr></tbody></table><h2 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to &quot;Databases&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=databases" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=databases</a>, fetched 2026-08-04 — 15 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Azure Cosmos DB</td><td>Collected</td><td><code>CosmosDB</code></td></tr><tr><td>Azure DocumentDB</td><td>Not collected</td><td>real gap — the 2025 vCore-based MongoDB service is a distinct resource provider from Cosmos DB</td></tr><tr><td>Azure SQL (umbrella)</td><td>Collected</td><td>see SQL DB / MI rows below, plus <code>SQLSERVER</code> (the logical <code>microsoft.sql/servers</code> resource)</td></tr><tr><td>Azure SQL Database</td><td>Collected</td><td><code>SQLDB</code></td></tr><tr><td>Azure SQL Managed Instance</td><td>Collected</td><td><code>SQLMI</code>, <code>SQLMIDB</code></td></tr><tr><td>SQL Server on Azure Virtual Machines</td><td>Collected (cross-category: Compute)</td><td><code>SQLVM</code></td></tr><tr><td>Azure Database for PostgreSQL</td><td>Collected</td><td><code>POSTGREFlexible</code> (flexible server only — single server was retired by Microsoft in 2024)</td></tr><tr><td>Azure Database for MySQL</td><td>Collected</td><td><code>MySQL</code>, <code>MySQLflexible</code></td></tr><tr><td>Azure Managed Redis</td><td>Collected</td><td><code>RedisCache</code> (covers <code>microsoft.cache/redisenterprise</code>)</td></tr><tr><td>Azure Database Migration Service</td><td>Collected (cross-category: Migration)</td><td><code>DatabaseMigrationServices</code></td></tr><tr><td>Azure Managed Instance for Apache Cassandra</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Data Factory</td><td>Not collected</td><td>real gap (also listed under Analytics)</td></tr><tr><td>Table Storage</td><td>Not collected</td><td>no dedicated collector for <code>microsoft.storage/storageaccounts/tableservices</code></td></tr><tr><td>Azure confidential ledger</td><td>Collected (cross-category: Security)</td><td><code>ConfidentialLedger</code></td></tr><tr><td>Azure HorizonDB</td><td>Not collected</td><td>real gap — new (2025) service</td></tr></tbody></table><p>We also collect <code>MariaDB</code> and <code>SQLPOOL</code> (elastic pools), neither of which appears in Microsoft&#39;s current catalogue — Azure Database for MariaDB was retired by Microsoft in September 2025, so that collector is now pointed at a decommissioned service rather than a coverage gap. We also collect <code>SQLSERVER</code> (the logical <code>microsoft.sql/servers</code> resource that hosts Azure SQL Database and Managed Instance) — Microsoft does not catalogue &quot;SQL Server&quot; as a separate product from the &quot;Azure SQL&quot; umbrella, which is why it has no dedicated row above.</p><h2 id="devops" tabindex="-1">DevOps <a class="header-anchor" href="#devops" aria-label="Permalink to &quot;DevOps&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=devops" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=devops</a>, fetched 2026-08-04 — 19 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Azure Artifacts</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Boards</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure DevOps (organization)</td><td>Collected</td><td><code>DevOpsProjects</code></td></tr><tr><td>Azure DevTest Labs</td><td>Collected</td><td><code>DevTestLabs</code></td></tr><tr><td>Azure Monitor</td><td>Collected (cross-category: Monitor)</td><td>22 Monitor collectors</td></tr><tr><td>Azure Pipelines</td><td>Collected</td><td><code>DevOpsPipelines</code>, <code>DevOpsAgentPools</code></td></tr><tr><td>Azure Repos</td><td>Collected</td><td><code>DevOpsRepositories</code></td></tr><tr><td>Azure Test Plans</td><td>Not collected</td><td>real gap</td></tr><tr><td>DevOps tool integrations</td><td>N/A</td><td>not a resource</td></tr><tr><td>Azure App Testing</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Managed Grafana</td><td>Not collected</td><td>real gap — no <code>microsoft.dashboard/grafana</code> collector anywhere in the estate</td></tr><tr><td>Microsoft Dev Box</td><td>Collected</td><td><code>DevBoxPools</code>, <code>DevCenters</code>, <code>DevCenterNetworkConnections</code></td></tr><tr><td>Azure Deployment Environments</td><td>Collected</td><td><code>DeploymentEnvironments</code></td></tr><tr><td>GitHub Advanced Security for Azure DevOps</td><td>Not collected</td><td>real gap</td></tr><tr><td>Microsoft Playwright Testing</td><td>Collected</td><td><code>PlaywrightTesting</code></td></tr><tr><td>GitHub Enterprise</td><td>N/A</td><td>not an Azure resource</td></tr><tr><td>GitHub Advanced Security</td><td>N/A</td><td>not an Azure resource</td></tr><tr><td>GitHub Copilot</td><td>N/A</td><td>not an Azure resource</td></tr><tr><td>Azure SRE Agent</td><td>Not collected</td><td>real gap — new (2026) service</td></tr></tbody></table><p>We also collect <code>ApiConnections</code>, <code>ChaosStudio</code>, <code>LabServices</code>, <code>LoadTesting</code>, <code>ManagedDevOpsPools</code> and <code>DevOpsServiceConnections</code>, none of which are separately listed on Microsoft&#39;s DevOps catalogue page (Chaos Studio is listed under Analytics there, <code>DevOpsServiceConnections</code> is a sub-object of an Azure DevOps project rather than its own product, and the rest are sub-features of things already counted above).</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><p>Microsoft does not publish &quot;General&quot; as a product category — it exists in the Azure portal&#39;s &quot;All services&quot; grouping for platform surfaces (support, billing, quotas, reservations) that don&#39;t belong to any service family, but Microsoft&#39;s own product catalogue doesn&#39;t enumerate it the way it does the other 17 categories. We are not inventing a sourced total for this one.</p><p>AzureScout&#39;s <code>General</code> category has 5 collectors: <code>Quotas</code>, <code>ReservationRecom</code>, <code>Reservations</code>, <code>ReservationUtilization</code>, <code>SupportTickets</code>. The one gap we can identify without a source to check against: <strong>Cost Management data itself is collected by a separate pipeline</strong> (<code>Get-ScoutCostInventory.ps1</code>, not a <code>manifests/collectors/General</code> definition) — it is not a gap so much as a different collection path from the rest of this page.</p><h2 id="hybrid-multicloud" tabindex="-1">Hybrid + multicloud <a class="header-anchor" href="#hybrid-multicloud" aria-label="Permalink to &quot;Hybrid + multicloud&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=hybrid-multicloud" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=hybrid-multicloud</a>, fetched 2026-08-04 — 14 products.</p><div class="warning custom-block"><p class="custom-block-title">This category is ambiguous — the marketing list and the portal category diverge</p><p>Microsoft&#39;s &quot;Hybrid + multicloud&quot; <em>product</em> catalogue is a marketing cross-listing (it includes Azure SQL Database, Azure ExpressRoute, Microsoft Sentinel — products that live natively in other categories and are tagged &quot;hybrid&quot; because they have a hybrid connectivity story). It is <strong>not</strong> the same shape as the Azure portal&#39;s <strong>Hybrid + multicloud</strong> category blade, which is what <a href="./category-structure.html">Category Structure</a> and our <code>Hybrid</code> collector folder are built against — that blade is organized around Azure Arc resource families (Arc servers, Arc Kubernetes, Arc data services, Azure Local/Stack HCI, VMware Solution, Stack Edge, Stack Hub). We&#39;re reporting against the resource families the portal blade actually exposes, not the marketing list, because that&#39;s the comparison the is asked for when someone wants the sub-services under a main category.</p></div><table tabindex="0"><thead><tr><th>Azure Arc / Hybrid resource family</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Arc-enabled servers</td><td>Collected</td><td><code>ARCServers</code>, <code>ArcServerOperationalData</code>, <code>ArcExtensions</code>, <code>ArcGateways</code></td></tr><tr><td>Arc-enabled Kubernetes</td><td>Collected</td><td><code>ArcKubernetes</code></td></tr><tr><td>Arc-enabled data services (data controllers)</td><td>Collected</td><td><code>ArcDataControllers</code></td></tr><tr><td>Arc-enabled SQL Server</td><td>Collected</td><td><code>ArcSQLServers</code></td></tr><tr><td>Arc-enabled SQL Managed Instance</td><td>Collected</td><td><code>ArcSQLManagedInstances</code></td></tr><tr><td>Arc Resource Bridge</td><td>Collected</td><td><code>ArcResourceBridge</code></td></tr><tr><td>Arc Sites</td><td>Collected</td><td><code>ArcSites</code></td></tr><tr><td><strong>Arc-enabled VMware vSphere</strong> (<code>Microsoft.ConnectedVMwarevSphere</code>)</td><td><strong>Not collected</strong></td><td>real gap — confirmed no collector references this resource provider</td></tr><tr><td><strong>Arc-enabled SCVMM</strong> (<code>Microsoft.ScVmm</code>)</td><td><strong>Not collected</strong></td><td>real gap — confirmed no collector references this resource provider</td></tr><tr><td><strong>Custom Locations</strong> (<code>Microsoft.ExtendedLocation/customLocations</code>)</td><td><strong>Not collected</strong></td><td>real gap — confirmed no collector references this resource type at all; every Arc resource bridge deployment creates one</td></tr><tr><td>Azure Local (Stack HCI) clusters</td><td>Collected</td><td><code>Clusters</code></td></tr><tr><td>Azure Local VMs</td><td>Collected</td><td><code>VirtualMachines</code> (<code>AZSC/ARMChild/AzureLocalVirtualMachineInstances</code>)</td></tr><tr><td>Azure Local gallery/marketplace images</td><td>Collected</td><td><code>GalleryImages</code>, <code>MarketplaceGalleryImages</code></td></tr><tr><td>Azure Local logical networks</td><td>Collected</td><td><code>LogicalNetworks</code></td></tr><tr><td>Azure Local storage containers</td><td>Collected</td><td><code>StorageContainers</code></td></tr><tr><td>Azure VMware Solution</td><td>Collected (cross-category: Compute)</td><td><code>VMWare</code></td></tr><tr><td>Azure Stack Edge</td><td>Collected (cross-category: Migration)</td><td><code>StackEdge</code></td></tr><tr><td>Azure Stack Hub</td><td><strong>Out of scope</strong></td><td>not a gap — Azure Scout does not cover Azure Stack Hub. Product decision, 2026-08-04. Do not re-raise this as missing coverage.</td></tr><tr><td>Azure Operator Nexus / Operator Service Manager</td><td>Not collected</td><td>real gap — telco-specific, likely low priority</td></tr><tr><td>Azure Storage Mover</td><td>Not collected</td><td>real gap</td></tr></tbody></table><p>This corrects the earlier claim that GalleryImages, MarketplaceGalleryImages and StorageContainers were missing — those three collectors exist and cover the <strong>Azure Local</strong> (Stack HCI) resource family. The real, confirmed gaps are the two Arc-enabled hypervisor-management resource providers (<code>Microsoft.ConnectedVMwarevSphere</code>, <code>Microsoft.ScVmm</code>) and Custom Locations, none of which have any collector referencing them anywhere in <code>manifests/collectors/</code>.</p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=identity" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=identity</a>, fetched 2026-08-04 — 4 products.</p><div class="warning custom-block"><p class="custom-block-title">This category doesn&#39;t fit a Collected/Not collected table</p><p>Microsoft&#39;s product catalogue counts <strong>Microsoft Entra ID</strong> as a single product; it doesn&#39;t break out Entra ID&#39;s internal object types (users, groups, app registrations, Conditional Access, PIM, etc.) into separate catalogue entries the way the Azure portal&#39;s Identity blade — and our 17 Identity collectors — do. So &quot;4 of 4&quot; would be true but not useful. All 4 Microsoft-catalogued identity products have at least one collector:</p></div><table tabindex="0"><thead><tr><th>Microsoft product</th><th>Status</th><th>AzureScout collector(s)</th></tr></thead><tbody><tr><td>Microsoft Entra ID</td><td>Collected</td><td>15 of the 17 Identity collectors (<code>Users</code>, <code>Groups</code>, <code>AppRegistrations</code>, <code>ConditionalAccess</code>, <code>DirectoryRoles</code>, <code>Domains</code>, <code>Licensing</code>, <code>ManagedIdentities</code>, <code>NamedLocations</code>, <code>PIMAssignments</code>, <code>RiskyUsers</code>, <code>SecurityPolicies</code>, <code>ServicePrincipals</code>, <code>AdminUnits</code>, <code>CrossTenantAccess</code>) — the remaining 2 (<code>ManagedIds</code>, an ARM <code>Microsoft.ManagedIdentity/userAssignedIdentities</code> collector distinct from the Entra-Graph <code>ManagedIdentities</code>; and <code>RoleAssignments</code>, Azure RBAC role assignments) are governance/RBAC primitives filed under the Identity manifest folder rather than Entra-ID directory objects</td></tr><tr><td>Microsoft Entra Domain Services</td><td>Collected (cross-category: Security)</td><td><code>EntraDomainServices</code></td></tr><tr><td>Microsoft Entra Verified ID</td><td>Not collected</td><td>real gap — no Verified ID credential collector</td></tr><tr><td>Microsoft Entra External ID</td><td>Not collected</td><td>real gap — no distinct External ID tenant/customer directory collector (our <code>Domains</code>/<code>Users</code> collectors run against the workforce tenant)</td></tr></tbody></table><h2 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=integration" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=integration</a>, fetched 2026-08-04 — 7 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>API Management</td><td>Collected</td><td><code>APIM</code></td></tr><tr><td>Azure Health Data Services</td><td>Collected</td><td><code>HealthDataServices</code></td></tr><tr><td>Event Grid</td><td>Collected</td><td><code>EventGrid</code></td></tr><tr><td>Logic Apps</td><td>Collected</td><td><code>LogicApps</code>, <code>LogicAppsCustomConnectors</code>, <code>IntegrationAccounts</code></td></tr><tr><td>Service Bus</td><td>Collected</td><td><code>ServiceBUS</code></td></tr><tr><td>Azure Web PubSub</td><td>Collected (cross-category: Web)</td><td><code>WebPubSub</code></td></tr><tr><td>Microsoft Energy Data Services</td><td>Not collected</td><td>real gap — vertical-specific, likely low priority</td></tr></tbody></table><p>We also collect <code>EventHubClusters</code> and <code>Relays</code>, neither separately catalogued by Microsoft under Integration (Event Hubs itself is catalogued under Analytics).</p><h2 id="internet-of-things" tabindex="-1">Internet of Things <a class="header-anchor" href="#internet-of-things" aria-label="Permalink to &quot;Internet of Things&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=internet-of-things" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=internet-of-things</a>, fetched 2026-08-04 — 16 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>API Management</td><td>Collected (cross-category: Integration)</td><td><code>APIM</code></td></tr><tr><td>Azure Cosmos DB</td><td>Collected (cross-category: Databases)</td><td><code>CosmosDB</code></td></tr><tr><td>Azure Digital Twins</td><td>Collected</td><td><code>DigitalTwins</code></td></tr><tr><td>Azure IoT Central</td><td>Collected</td><td><code>IoTCentral</code></td></tr><tr><td>Azure IoT Edge</td><td>Not collected</td><td>real gap — no distinct IoT Edge deployment collector</td></tr><tr><td>Azure IoT Hub</td><td>Collected</td><td><code>IOTHubs</code></td></tr><tr><td>Azure IoT Operations</td><td>Not collected</td><td>real gap — new (2024) Arc-enabled Kubernetes IoT workload, no collector</td></tr><tr><td>Azure Functions</td><td>Collected (cross-category: Web)</td><td><code>FunctionApps</code></td></tr><tr><td>Azure Machine Learning</td><td>Collected (cross-category: AI)</td><td><code>MachineLearning</code></td></tr><tr><td>Azure Maps</td><td>Collected</td><td><code>Maps</code></td></tr><tr><td>Azure Stream Analytics</td><td>Collected (cross-category: Analytics)</td><td><code>Streamanalytics</code></td></tr><tr><td>Notification Hubs</td><td>Collected (cross-category: Web)</td><td><code>NotificationHubs</code></td></tr><tr><td>Windows for IoT</td><td>N/A</td><td>operating system, not an ARM resource</td></tr><tr><td>Logic Apps</td><td>Collected (cross-category: Integration)</td><td><code>LogicApps</code></td></tr><tr><td>Azure Sphere</td><td>Not collected</td><td>real gap — Microsoft is retiring Azure Sphere (end of support 2026), low priority</td></tr><tr><td>Event Grid</td><td>Collected (cross-category: Integration)</td><td><code>EventGrid</code></td></tr></tbody></table><p>We also collect <code>DeviceProvisioningServices</code>, <code>DeviceUpdate</code> and <code>DefenderForIoT</code>, none separately catalogued by Microsoft under Internet of Things (Defender for IoT is catalogued under Security).</p><h2 id="management-and-governance" tabindex="-1">Management and governance <a class="header-anchor" href="#management-and-governance" aria-label="Permalink to &quot;Management and governance&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=management-and-governance" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=management-and-governance</a>, fetched 2026-08-04 — 25 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Azure Copilot</td><td>N/A</td><td>assistant experience, not an inventoried resource</td></tr><tr><td>Automation</td><td>Collected</td><td><code>AutomationAccounts</code></td></tr><tr><td>Azure Advisor</td><td>Collected</td><td><code>AdvisorScore</code></td></tr><tr><td>Defender External Attack Surface Management</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Backup</td><td>Collected</td><td><code>Backup</code>, <code>BackupInstances</code>, <code>RecoveryVault</code></td></tr><tr><td>Azure Blueprints</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Lighthouse</td><td>Collected</td><td><code>LighthouseDelegations</code></td></tr><tr><td>Azure Managed Applications</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Migrate</td><td>Collected (cross-category: Migration)</td><td><code>AzureMigrateProjects</code>, <code>AzureMigrateAssessments</code></td></tr><tr><td>Microsoft Purview</td><td>Collected (cross-category: Analytics)</td><td><code>Purview</code></td></tr><tr><td>Azure Monitor</td><td>Collected (cross-category: Monitor)</td><td>22 Monitor collectors</td></tr><tr><td>Azure Policy</td><td>Collected</td><td><code>PolicyAssignments</code>, <code>PolicyDefinitions</code>, <code>PolicySetDefinitions</code>, <code>PolicyComplianceStates</code></td></tr><tr><td>Azure Resource Manager</td><td>N/A</td><td>control-plane API, not itself a resource</td></tr><tr><td>Azure Resource Manager templates</td><td>N/A</td><td>deployment artifact, not a resource</td></tr><tr><td>Azure Chaos Studio</td><td>Collected (cross-category: DevOps)</td><td><code>ChaosStudio</code></td></tr><tr><td>Azure Site Recovery</td><td>Not collected</td><td>real gap — no distinct Site Recovery replication collector (Recovery Vault container is collected, replication items are not)</td></tr><tr><td>Cloud Shell</td><td>N/A</td><td>not an inventoried resource</td></tr><tr><td>Microsoft Cost Management</td><td>Collected (separate pipeline)</td><td><code>Get-ScoutCostInventory.ps1</code>, not a <code>manifests/collectors</code> definition</td></tr><tr><td>Azure Managed Grafana</td><td>Not collected</td><td>real gap (also listed under DevOps)</td></tr><tr><td>Azure Network Watcher</td><td>Collected (cross-category: Networking)</td><td><code>NetworkWatchers</code></td></tr><tr><td>Azure Traffic Manager</td><td>Collected (cross-category: Networking)</td><td><code>TrafficManager</code></td></tr><tr><td>Azure Automanage</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Resource Mover</td><td>Not collected</td><td>real gap</td></tr><tr><td>Update management center</td><td>Not collected</td><td>real gap — distinct from <code>MaintenanceConfigurations</code>, which we do collect</td></tr><tr><td>Azure SRE Agent</td><td>Not collected</td><td>real gap (also listed under DevOps)</td></tr></tbody></table><p>We also collect <code>AllSubscriptions</code>, <code>Budgets</code>, <code>CustomRoleDefinitions</code>, <code>ManagementGroups</code>, <code>MaintenanceConfigurations</code> and <code>ResourceLocks</code>, none separately catalogued as products by Microsoft (they&#39;re governance primitives, not marketed services).</p><h2 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=migration" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=migration</a>, fetched 2026-08-04 — 6 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Azure Database Migration Service</td><td>Collected</td><td><code>DatabaseMigrationServices</code></td></tr><tr><td>Azure Migrate</td><td>Collected</td><td><code>AzureMigrateProjects</code>, <code>AzureMigrateAssessments</code>, <code>AzureMigrateDiscoverySites</code></td></tr><tr><td>Azure Site Recovery</td><td>Not collected</td><td>real gap (also listed under Management and governance)</td></tr><tr><td>Microsoft Cost Management</td><td>Collected (separate pipeline)</td><td><code>Get-ScoutCostInventory.ps1</code></td></tr><tr><td>Azure Data Box</td><td>Collected</td><td><code>DataBox</code></td></tr><tr><td>Azure Storage Mover</td><td>Not collected</td><td>real gap (also listed under Hybrid + multicloud)</td></tr></tbody></table><p>Migration is the one category where our collector-name coverage figure (6 of 6 in the summary table above) is misleading: two of Microsoft&#39;s six listed products (Site Recovery, Storage Mover) are not actually collected — the &quot;6 of 6&quot; only holds if <code>StackEdge</code> is counted as the Migration category&#39;s own Data Box/Stack Edge coverage, which it is, but Site Recovery and Storage Mover remain real gaps.</p><h2 id="monitor" tabindex="-1">Monitor <a class="header-anchor" href="#monitor" aria-label="Permalink to &quot;Monitor&quot;">​</a></h2><p>Source: Microsoft Learn, <a href="https://learn.microsoft.com/azure/azure-monitor/fundamentals/overview" target="_blank" rel="noreferrer">Azure Monitor overview</a> and <a href="https://learn.microsoft.com/azure/azure-monitor/fundamentals/enterprise-monitoring-architecture" target="_blank" rel="noreferrer">Azure Monitor enterprise monitoring architecture</a>, fetched 2026-08-04. Monitor has no entry on Microsoft&#39;s product-category marketing catalogue (<code>?categories=monitor</code> 404s), so this list is the set of named Azure Monitor sub-components those Learn articles describe, not a marketing product list.</p><table tabindex="0"><thead><tr><th>Azure Monitor component</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Application Insights</td><td>Collected</td><td><code>AppInsights</code>, <code>AppInsightsAvailabilityTests</code>, <code>AppInsightsWebTests</code>, <code>AppInsightsProactiveDetection</code></td></tr><tr><td>Log Analytics workspaces</td><td>Collected</td><td><code>Workspaces</code></td></tr><tr><td>Log Analytics saved searches / linked services</td><td>Collected</td><td><code>LAWorkspaceSavedSearches</code>, <code>LAWorkspaceLinkedServices</code></td></tr><tr><td>Log Analytics solutions</td><td>Collected</td><td><code>LAWorkspaceSolutions</code></td></tr><tr><td>Azure Monitor managed service for Prometheus</td><td>Not collected</td><td>real gap — no collector for Prometheus rule groups / Azure Monitor workspaces</td></tr><tr><td>Metric alert rules</td><td>Collected</td><td><code>MetricAlertRules</code></td></tr><tr><td>Log/scheduled query alert rules</td><td>Collected</td><td><code>ScheduledQueryRules</code></td></tr><tr><td>Activity log alert rules</td><td>Collected</td><td><code>ActivityLogAlertRules</code></td></tr><tr><td>Smart detector alert rules</td><td>Collected</td><td><code>SmartDetectorAlertRules</code></td></tr><tr><td>Action groups</td><td>Collected</td><td><code>ActionGroups</code></td></tr><tr><td>Autoscale settings</td><td>Collected</td><td><code>AutoscaleSettings</code></td></tr><tr><td>Diagnostic settings</td><td>Collected</td><td><code>ResourceDiagnosticSettings</code>, <code>SubscriptionDiagnosticSettings</code></td></tr><tr><td>Data collection rules / endpoints</td><td>Collected</td><td><code>DataCollectionRules</code>, <code>DataCollectionEndpoints</code></td></tr><tr><td>Workbooks</td><td>Collected</td><td><code>MonitorWorkbooks</code></td></tr></tbody></table><p>We also collect <code>MonitorMetricsIngestion</code>, <code>MonitorPrivateLinkScopes</code> and <code>Outages</code>, all genuine Monitor surfaces the two source articles don&#39;t call out individually. Azure Managed Grafana, which Learn documentation frequently pairs with Monitor visualization, is tracked as a gap under DevOps and Management and governance instead, since that is where Microsoft&#39;s own product catalogue places it.</p><h2 id="networking" tabindex="-1">Networking <a class="header-anchor" href="#networking" aria-label="Permalink to &quot;Networking&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=networking" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=networking</a>, fetched 2026-08-04 — 22 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Azure Application Gateway</td><td>Collected</td><td><code>ApplicationGateways</code></td></tr><tr><td>Azure Bastion</td><td>Collected</td><td><code>BastionHosts</code></td></tr><tr><td>Azure DDoS Protection</td><td>Collected (cross-category: Security)</td><td><code>DdosProtectionPlans</code></td></tr><tr><td>Azure DNS</td><td>Collected</td><td><code>PublicDNS</code>, <code>PrivateDNS</code></td></tr><tr><td>Azure ExpressRoute</td><td>Collected</td><td><code>ExpressRoute</code></td></tr><tr><td>Azure Firewall</td><td>Collected</td><td><code>AzureFirewall</code></td></tr><tr><td>Azure Content Delivery Network</td><td>Not collected</td><td>real gap — no <code>microsoft.cdn/profiles</code> collector (WAF policies attached to CDN are collected via <code>WafPolicies</code>, the CDN profile itself is not)</td></tr><tr><td>Azure Route Server</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure Web Application Firewall</td><td>Collected</td><td><code>WafPolicies</code></td></tr><tr><td>Azure Front Door</td><td>Collected</td><td><code>Frontdoor</code></td></tr><tr><td>Azure Network Function Manager</td><td>Not collected</td><td>real gap — telco-specific, likely low priority</td></tr><tr><td>Azure Virtual Network Manager</td><td>Not collected</td><td>real gap</td></tr><tr><td>Azure NAT Gateway</td><td>Collected</td><td><code>NATGateway</code></td></tr><tr><td>Azure Load Balancer</td><td>Collected</td><td><code>LoadBalancer</code></td></tr><tr><td>Azure Private Link</td><td>Collected</td><td><code>PrivateEndpoint</code></td></tr><tr><td>Azure Firewall Manager</td><td>Not collected</td><td>real gap — firewall policies specifically, distinct from <code>AzureFirewall</code> instances</td></tr><tr><td>Azure Network Watcher</td><td>Collected</td><td><code>NetworkWatchers</code></td></tr><tr><td>Azure Traffic Manager</td><td>Collected</td><td><code>TrafficManager</code></td></tr><tr><td>Azure Virtual Network</td><td>Collected</td><td><code>VirtualNetwork</code>, <code>vNETPeering</code></td></tr><tr><td>Azure Virtual WAN</td><td>Collected</td><td><code>VirtualWAN</code></td></tr><tr><td>Azure VPN Gateway</td><td>Collected</td><td><code>VirtualNetworkGateways</code></td></tr><tr><td>Azure Enclave</td><td>Not collected</td><td>real gap — confidential-computing networking, new</td></tr></tbody></table><p>We also collect <code>Connections</code>, <code>NetworkInterface</code>, <code>NetworkSecurityGroup</code>, <code>PublicIP</code> and <code>RouteTables</code>, all genuine Networking resources Microsoft&#39;s product catalogue doesn&#39;t list as separate &quot;products&quot; (they&#39;re sub-resources of Virtual Network there).</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=security" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=security</a>, fetched 2026-08-04 — 19 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Azure App Configuration</td><td>Collected (cross-category: DevOps)</td><td><code>AppConfiguration</code></td></tr><tr><td>Azure Application Gateway</td><td>Collected (cross-category: Networking)</td><td><code>ApplicationGateways</code></td></tr><tr><td>Microsoft Entra Domain Services</td><td>Collected</td><td><code>EntraDomainServices</code></td></tr><tr><td>Microsoft Defender for Cloud</td><td>Collected</td><td><code>DefenderAlerts</code>, <code>DefenderAssessments</code>, <code>DefenderPricing</code>, <code>DefenderSecureScore</code></td></tr><tr><td>Defender External Attack Surface Management</td><td>Not collected</td><td>real gap (also listed under Management and governance)</td></tr><tr><td>Azure Bastion</td><td>Collected (cross-category: Networking)</td><td><code>BastionHosts</code></td></tr><tr><td>Azure DDoS Protection</td><td>Collected</td><td><code>DdosProtectionPlans</code></td></tr><tr><td>Azure Cloud HSM</td><td>Collected</td><td><code>CloudHSM</code></td></tr><tr><td>Azure Firewall</td><td>Collected (cross-category: Networking)</td><td><code>AzureFirewall</code></td></tr><tr><td>Azure Firewall Manager</td><td>Not collected</td><td>real gap (also listed under Networking)</td></tr><tr><td>Azure Front Door</td><td>Collected (cross-category: Networking)</td><td><code>Frontdoor</code></td></tr><tr><td>Azure Information Protection</td><td>Not collected</td><td>real gap — no label/policy collector</td></tr><tr><td>Microsoft Sentinel</td><td>Collected</td><td><code>Sentinel</code></td></tr><tr><td>Azure Key Vault</td><td>Collected</td><td><code>Vault</code>, <code>KeyVaultKeys</code>, <code>KeyVaultSecrets</code></td></tr><tr><td>Azure confidential ledger</td><td>Collected</td><td><code>ConfidentialLedger</code></td></tr><tr><td>Azure VPN Gateway</td><td>Collected (cross-category: Networking)</td><td><code>VirtualNetworkGateways</code></td></tr><tr><td>Azure Web Application Firewall</td><td>Collected (cross-category: Networking)</td><td><code>WafPolicies</code></td></tr><tr><td>Microsoft Azure Attestation</td><td>Not collected</td><td>real gap</td></tr><tr><td>Microsoft Security Copilot</td><td>Not collected</td><td>real gap (also listed under AI + Machine Learning)</td></tr></tbody></table><p>We also collect <code>AppComplianceAutomation</code>, <code>ApplicationSecurityGroups</code>, <code>ManagedHSM</code> and <code>ArtifactSigning</code> (<code>microsoft.codesigning/codesigningaccounts</code> — Azure Artifact Signing, formerly Trusted Signing), none separately catalogued as products by Microsoft&#39;s Security page (Artifact Signing has its own product page at <a href="https://azure.microsoft.com/en-us/products/artifact-signing" target="_blank" rel="noreferrer">azure.microsoft.com/products/artifact-signing</a> but is not tagged into the <code>?categories=security</code> catalogue listing checked above).</p><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=storage" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=storage</a>, fetched 2026-08-04 — 19 products.</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>Archive Storage</td><td>Collected (as a tier, not a resource)</td><td><code>StorageAccounts</code> (tier is a property, not a separate resource type)</td></tr><tr><td>Azure Managed Lustre</td><td>Not collected</td><td>real gap — new (2024) HPC file system</td></tr><tr><td>Azure Backup</td><td>Collected (cross-category: Management)</td><td><code>Backup</code>, <code>BackupInstances</code></td></tr><tr><td>Azure Data Lake Storage</td><td>Collected (cross-category: Analytics)</td><td><code>StorageAccounts</code></td></tr><tr><td>Azure Data Share</td><td>Not collected</td><td>real gap (also listed under Analytics)</td></tr><tr><td>Azure Files</td><td>Collected</td><td><code>FileShares</code></td></tr><tr><td>Azure Storage Actions</td><td>Not collected</td><td>real gap — new (2024) storage task automation</td></tr><tr><td>Azure NetApp Files</td><td>Collected</td><td><code>NetApp</code></td></tr><tr><td>Azure Blob Storage</td><td>Collected</td><td><code>BlobContainers</code></td></tr><tr><td>Azure Data Box</td><td>Collected (cross-category: Migration)</td><td><code>DataBox</code></td></tr><tr><td>Azure Disk Storage</td><td>Collected</td><td><code>VMDisk</code>, <code>Snapshots</code>, <code>DiskEncryptionSets</code></td></tr><tr><td>Azure confidential ledger</td><td>Collected (cross-category: Security)</td><td><code>ConfidentialLedger</code></td></tr><tr><td>Azure Elastic SAN</td><td>Collected</td><td><code>ElasticSan</code></td></tr><tr><td>Queue Storage</td><td>Not collected</td><td>real gap — no <code>microsoft.storage/storageaccounts/queueservices</code> collector</td></tr><tr><td>Storage Accounts</td><td>Collected</td><td><code>StorageAccounts</code></td></tr><tr><td>Storage Explorer</td><td>N/A</td><td>a client tool, not an Azure resource</td></tr><tr><td>Azure Container Storage</td><td>Not collected</td><td>real gap (also listed under Containers)</td></tr><tr><td>Azure Storage Discovery</td><td>Not collected</td><td>real gap — new (2025) estate-wide storage insights service</td></tr><tr><td>Azure Storage Mover</td><td>Not collected</td><td>real gap (also listed under Hybrid + multicloud and Migration)</td></tr></tbody></table><p>We also collect <code>EdgeHardwareCenter</code>, <code>LifecyclePolicies</code>, <code>PartnerStorage</code>, and <code>StorageSync</code>, none separately catalogued as products by Microsoft&#39;s Storage page.</p><h2 id="web-mobile" tabindex="-1">Web &amp; Mobile <a class="header-anchor" href="#web-mobile" aria-label="Permalink to &quot;Web &amp; Mobile&quot;">​</a></h2><p>Source: <a href="https://azure.microsoft.com/en-us/products/?categories=web" target="_blank" rel="noreferrer">azure.microsoft.com/products?categories=web</a> and <a href="https://azure.microsoft.com/en-us/products/?categories=mobile" target="_blank" rel="noreferrer">?categories=mobile</a>, fetched 2026-08-04 — 14 Web products, 8 Mobile products, 15 distinct after dedup (Mobile is almost entirely a subset of Web, plus &quot;Azure AI Services&quot;).</p><table tabindex="0"><thead><tr><th>Microsoft service</th><th>Status</th><th>AzureScout collector</th></tr></thead><tbody><tr><td>API Management</td><td>Collected (cross-category: Integration)</td><td><code>APIM</code></td></tr><tr><td>App Configuration</td><td>Collected (cross-category: DevOps)</td><td><code>AppConfiguration</code></td></tr><tr><td>App Service</td><td>Collected</td><td><code>APPServices</code>, <code>APPServicePlan</code>, <code>DeploymentSlots</code>, <code>AppServiceEnvironments</code>, <code>AppServiceCertificates</code>, <code>AppServiceDomains</code></td></tr><tr><td>Azure AI Search</td><td>Collected (cross-category: AI)</td><td><code>SearchServices</code></td></tr><tr><td>Azure Maps</td><td>Collected (cross-category: IoT)</td><td><code>Maps</code></td></tr><tr><td>Azure AI Services</td><td>Collected (cross-category: AI)</td><td><code>AzureAI</code>, <code>AppliedAIServices</code></td></tr><tr><td>Azure SignalR Service</td><td>Collected</td><td><code>SignalR</code></td></tr><tr><td>Azure Content Delivery Network</td><td>Not collected</td><td>real gap (also listed under Networking)</td></tr><tr><td>Notification Hubs</td><td>Collected</td><td><code>NotificationHubs</code></td></tr><tr><td>Static Web Apps</td><td>Collected</td><td><code>StaticWebApps</code></td></tr><tr><td>Azure Communication Services</td><td>Collected</td><td><code>CommunicationServices</code></td></tr><tr><td>Azure Web PubSub</td><td>Collected</td><td><code>WebPubSub</code></td></tr><tr><td>Azure Fluid Relay</td><td>Collected</td><td><code>FluidRelay</code></td></tr><tr><td>Microsoft Playwright Testing</td><td>Collected (cross-category: DevOps)</td><td><code>PlaywrightTesting</code></td></tr><tr><td>Azure Container Apps</td><td>Collected (cross-category: Containers)</td><td><code>ContainerApp</code></td></tr></tbody></table><p>We also collect <code>FunctionApps</code> and <code>SpringApps</code> under the <code>Web</code> folder, both cross-listed under Compute in Microsoft&#39;s catalogue rather than Web.</p><h2 id="summary-of-confirmed-unambiguous-gaps" tabindex="-1">Summary of confirmed, unambiguous gaps <a class="header-anchor" href="#summary-of-confirmed-unambiguous-gaps" aria-label="Permalink to &quot;Summary of confirmed, unambiguous gaps&quot;">​</a></h2><p>Every &quot;real gap&quot; row above was verified with <code>grep -ril</code> across <code>manifests/collectors/</code> for the relevant resource-type string before being marked; none are guesses. The highest-value gaps — services that are GA, not retiring, and have no collector anywhere in the estate — are:</p><ul><li><strong>Custom Locations</strong> (<code>Microsoft.ExtendedLocation/customLocations</code>) — Hybrid</li><li><strong>Arc-enabled VMware vSphere</strong> (<code>Microsoft.ConnectedVMwarevSphere</code>) — Hybrid</li><li><strong>Arc-enabled SCVMM</strong> (<code>Microsoft.ScVmm</code>) — Hybrid</li><li><strong>Azure Managed Grafana</strong> (<code>Microsoft.Dashboard/grafana</code>) — DevOps / Management and governance</li><li><strong>Azure Data Factory</strong> (<code>Microsoft.DataFactory/factories</code>) — Analytics / Databases</li><li><strong>Microsoft Fabric</strong> — Analytics</li><li><strong>Azure Content Delivery Network</strong> (<code>Microsoft.Cdn/profiles</code>) — Networking / Web &amp; Mobile</li><li><strong>Azure Batch</strong> (<code>Microsoft.Batch/batchAccounts</code>) — Compute</li><li><strong>Azure Dedicated Host</strong> (<code>Microsoft.Compute/dedicatedHosts</code>) — Compute</li><li><strong>Azure Kubernetes Fleet Manager</strong> (<code>Microsoft.ContainerService/fleets</code>) — Containers</li><li><strong>Azure Site Recovery replication items</strong> — Migration / Management and governance (the Recovery Vault container is collected; replication items are not)</li></ul>',85)])])}const h=e(c,[["render",a]]);export{p as __pageData,h as default};
